/**
 * Source lists for the static issue article, read at build time from
 * src/data/sources/{id}.json (generated by scripts/build-issue-sources.mjs).
 *
 * Build-time only: import from .astro pages, never from client components.
 * The interactive readers get the same entries as `sourceList` inside
 * public/issues/{id}.json.
 */
import type { SourceEntry } from './issue-types';

interface SourceFile {
  id: string;
  entries: SourceEntry[];
}

const modules = import.meta.glob<SourceFile>('./sources/*.json', {
  eager: true,
  import: 'default',
});

const byId = new Map<string, SourceEntry[]>();
for (const file of Object.values(modules)) byId.set(file.id, file.entries);

export function getIssueSourceList(id: string): SourceEntry[] | undefined {
  return byId.get(id);
}
